begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local search_path = public, extensions;
select ok((select relrowsecurity from pg_class where oid='public.moments'::regclass), 'moments has RLS');
select ok((select relrowsecurity from pg_class where oid='public.diaries'::regclass), 'diaries has RLS');
select ok((select relrowsecurity from pg_class where oid='public.chats'::regclass), 'chats has RLS');
select ok((select relrowsecurity from pg_class where oid='public.drafts'::regclass), 'drafts has RLS');
select ok((select relrowsecurity from pg_class where oid='public.settings'::regclass), 'settings has RLS');
select ok((select relrowsecurity from pg_class where oid='public.ai_usage'::regclass), 'ai_usage has RLS');
select is((select count(*)::int from pg_publication_tables where pubname='supabase_realtime' and tablename in ('moments','diaries','chats','drafts','settings')),5,'All synced tables published');
select is((select count(*)::int from cron.job where jobname='purge-capture-tombstones' and active and schedule='17 3 * * *'),1,'Daily purge scheduled');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.moments where user_id='00000000-0000-4000-8000-000000000002'),0,'A cannot read B moments');
select results_eq($$update public.moments set updated_at=now() where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot update B moments');
select results_eq($$delete from public.moments where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot delete B moments');
select is((select count(*)::int from public.diaries where user_id='00000000-0000-4000-8000-000000000002'),0,'A cannot read B diaries');
select results_eq($$update public.diaries set updated_at=now() where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot update B diaries');
select results_eq($$delete from public.diaries where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot delete B diaries');
select is((select count(*)::int from public.chats where user_id='00000000-0000-4000-8000-000000000002'),0,'A cannot read B chats');
select results_eq($$update public.chats set updated_at=now() where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot update B chats');
select results_eq($$delete from public.chats where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot delete B chats');
select is((select count(*)::int from public.drafts where user_id='00000000-0000-4000-8000-000000000002'),0,'A cannot read B drafts');
select results_eq($$update public.drafts set updated_at=now() where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot update B drafts');
select results_eq($$delete from public.drafts where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot delete B drafts');
select is((select count(*)::int from public.settings where user_id='00000000-0000-4000-8000-000000000002'),0,'A cannot read B settings');
select results_eq($$update public.settings set updated_at=now() where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot update B settings');
select results_eq($$delete from public.settings where user_id='00000000-0000-4000-8000-000000000002' returning 1$$,array[]::integer[],'A cannot delete B settings');
select is((select count(*)::int from public.ai_usage where user_id='00000000-0000-4000-8000-000000000002'),0,'A cannot read B ai_usage');
select throws_ok($$insert into public.ai_usage values ('00000000-0000-4000-8000-000000000001','2026-10-21','chat',1)$$,'42501',null,'Client cannot write usage');
select throws_ok($$update public.ai_usage set count=999$$,'42501',null,'Client cannot write usage');
select throws_ok($$delete from public.ai_usage$$,'42501',null,'Client cannot write usage');
select is(public.sync_push('[{"table": "moments", "row": {"id": "10000000-0000-4000-8000-000000000011", "text": "Changed moment", "date": "2026-10-20", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T11:00:00Z"}}]'::jsonb)->'stale','["10000000-0000-4000-8000-000000000011"]'::jsonb,'moments older write is stale');
select is(public.sync_push('[{"table": "moments", "row": {"id": "10000000-0000-4000-8000-000000000011", "text": "Changed moment", "date": "2026-10-20", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T12:00:00Z"}}]'::jsonb)->'stale','["10000000-0000-4000-8000-000000000011"]'::jsonb,'moments equal write is stale');
select is((select updated_at from moments where id='10000000-0000-4000-8000-000000000011'),'2026-10-20T12:00:00Z'::timestamptz,'moments stale writes unchanged');
select set_config('test.previous_sync',(select synced_at::text from moments where id='10000000-0000-4000-8000-000000000011'),true);
select is(public.sync_push('[{"table": "moments", "row": {"id": "10000000-0000-4000-8000-000000000011", "text": "Changed moment", "date": "2026-10-20", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T13:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z"}}]'::jsonb)->'applied','["10000000-0000-4000-8000-000000000011"]'::jsonb,'moments newer write applied');
select ok((select synced_at > current_setting('test.previous_sync')::timestamptz from moments where id='10000000-0000-4000-8000-000000000011'),'moments synced_at increases, ignores client value');
select is((select user_id from moments where id='10000000-0000-4000-8000-000000000011'),'00000000-0000-4000-8000-000000000001'::uuid,'moments ownership cannot be forged through sync');
select is(public.sync_push('[{"table": "moments", "row": {"id": "10000000-0000-4000-8000-000000000011", "text": "Changed moment", "date": "2026-10-20", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T14:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": "2026-10-20T14:00:00Z"}}]'::jsonb)->'applied','["10000000-0000-4000-8000-000000000011"]'::jsonb,'moments deletion applied');
select ok((select text='' from moments where id='10000000-0000-4000-8000-000000000011'),'moments tombstone clears all words');
select is(public.sync_push('[{"table": "moments", "row": {"id": "10000000-0000-4000-8000-000000000011", "text": "Changed moment", "date": "2026-10-20", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T15:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": null}}]'::jsonb)->'applied','["10000000-0000-4000-8000-000000000011"]'::jsonb,'moments later edit revives row');
select ok((select deleted_at is null from moments where id='10000000-0000-4000-8000-000000000011'),'moments revived');
select is(public.sync_push('[{"table": "diaries", "row": {"id": "92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6", "text": "Changed diary", "date": "2026-10-20", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T11:00:00Z"}}]'::jsonb)->'stale','["92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6"]'::jsonb,'diaries older write is stale');
select is(public.sync_push('[{"table": "diaries", "row": {"id": "92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6", "text": "Changed diary", "date": "2026-10-20", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T12:00:00Z"}}]'::jsonb)->'stale','["92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6"]'::jsonb,'diaries equal write is stale');
select is((select updated_at from diaries where id='92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6'),'2026-10-20T12:00:00Z'::timestamptz,'diaries stale writes unchanged');
select set_config('test.previous_sync',(select synced_at::text from diaries where id='92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6'),true);
select is(public.sync_push('[{"table": "diaries", "row": {"id": "92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6", "text": "Changed diary", "date": "2026-10-20", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T13:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z"}}]'::jsonb)->'applied','["92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6"]'::jsonb,'diaries newer write applied');
select ok((select synced_at > current_setting('test.previous_sync')::timestamptz from diaries where id='92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6'),'diaries synced_at increases, ignores client value');
select is((select user_id from diaries where id='92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6'),'00000000-0000-4000-8000-000000000001'::uuid,'diaries ownership cannot be forged through sync');
select is(public.sync_push('[{"table": "diaries", "row": {"id": "92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6", "text": "Changed diary", "date": "2026-10-20", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T14:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": "2026-10-20T14:00:00Z"}}]'::jsonb)->'applied','["92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6"]'::jsonb,'diaries deletion applied');
select ok((select text='' from diaries where id='92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6'),'diaries tombstone clears all words');
select is(public.sync_push('[{"table": "diaries", "row": {"id": "92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6", "text": "Changed diary", "date": "2026-10-20", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T15:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": null}}]'::jsonb)->'applied','["92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6"]'::jsonb,'diaries later edit revives row');
select ok((select deleted_at is null from diaries where id='92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6'),'diaries revived');
select is(public.sync_push('[{"table": "chats", "row": {"id": "20000000-0000-4000-8000-000000000001", "date": "2026-10-20", "messages": [{"role": "user", "content": "Changed chat"}], "state": {"input": "Private input"}, "saved_moment_ids": ["10000000-0000-4000-8000-000000000011"], "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T11:00:00Z"}}]'::jsonb)->'stale','["20000000-0000-4000-8000-000000000001"]'::jsonb,'chats older write is stale');
select is(public.sync_push('[{"table": "chats", "row": {"id": "20000000-0000-4000-8000-000000000001", "date": "2026-10-20", "messages": [{"role": "user", "content": "Changed chat"}], "state": {"input": "Private input"}, "saved_moment_ids": ["10000000-0000-4000-8000-000000000011"], "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T12:00:00Z"}}]'::jsonb)->'stale','["20000000-0000-4000-8000-000000000001"]'::jsonb,'chats equal write is stale');
select is((select updated_at from chats where id='20000000-0000-4000-8000-000000000001'),'2026-10-20T12:00:00Z'::timestamptz,'chats stale writes unchanged');
select set_config('test.previous_sync',(select synced_at::text from chats where id='20000000-0000-4000-8000-000000000001'),true);
select is(public.sync_push('[{"table": "chats", "row": {"id": "20000000-0000-4000-8000-000000000001", "date": "2026-10-20", "messages": [{"role": "user", "content": "Changed chat"}], "state": {"input": "Private input"}, "saved_moment_ids": ["10000000-0000-4000-8000-000000000011"], "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T13:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z"}}]'::jsonb)->'applied','["20000000-0000-4000-8000-000000000001"]'::jsonb,'chats newer write applied');
select ok((select synced_at > current_setting('test.previous_sync')::timestamptz from chats where id='20000000-0000-4000-8000-000000000001'),'chats synced_at increases, ignores client value');
select is((select user_id from chats where id='20000000-0000-4000-8000-000000000001'),'00000000-0000-4000-8000-000000000001'::uuid,'chats ownership cannot be forged through sync');
select is(public.sync_push('[{"table": "chats", "row": {"id": "20000000-0000-4000-8000-000000000001", "date": "2026-10-20", "messages": [{"role": "user", "content": "Changed chat"}], "state": {"input": "Private input"}, "saved_moment_ids": ["10000000-0000-4000-8000-000000000011"], "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T14:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": "2026-10-20T14:00:00Z"}}]'::jsonb)->'applied','["20000000-0000-4000-8000-000000000001"]'::jsonb,'chats deletion applied');
select ok((select messages='[]'::jsonb and state='{}'::jsonb and saved_moment_ids='{}'::uuid[] from chats where id='20000000-0000-4000-8000-000000000001'),'chats tombstone clears all words');
select is(public.sync_push('[{"table": "chats", "row": {"id": "20000000-0000-4000-8000-000000000001", "date": "2026-10-20", "messages": [{"role": "user", "content": "Changed chat"}], "state": {"input": "Private input"}, "saved_moment_ids": ["10000000-0000-4000-8000-000000000011"], "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T15:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": null}}]'::jsonb)->'applied','["20000000-0000-4000-8000-000000000001"]'::jsonb,'chats later edit revives row');
select ok((select deleted_at is null from chats where id='20000000-0000-4000-8000-000000000001'),'chats revived');
select is(public.sync_push('[{"table": "drafts", "row": {"id": "30000000-0000-4000-8000-000000000001", "date": "2026-10-20", "kind": "quick", "text": "Changed draft", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T11:00:00Z"}}]'::jsonb)->'stale','["30000000-0000-4000-8000-000000000001"]'::jsonb,'drafts older write is stale');
select is(public.sync_push('[{"table": "drafts", "row": {"id": "30000000-0000-4000-8000-000000000001", "date": "2026-10-20", "kind": "quick", "text": "Changed draft", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T12:00:00Z"}}]'::jsonb)->'stale','["30000000-0000-4000-8000-000000000001"]'::jsonb,'drafts equal write is stale');
select is((select updated_at from drafts where id='30000000-0000-4000-8000-000000000001'),'2026-10-20T12:00:00Z'::timestamptz,'drafts stale writes unchanged');
select set_config('test.previous_sync',(select synced_at::text from drafts where id='30000000-0000-4000-8000-000000000001'),true);
select is(public.sync_push('[{"table": "drafts", "row": {"id": "30000000-0000-4000-8000-000000000001", "date": "2026-10-20", "kind": "quick", "text": "Changed draft", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T13:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z"}}]'::jsonb)->'applied','["30000000-0000-4000-8000-000000000001"]'::jsonb,'drafts newer write applied');
select ok((select synced_at > current_setting('test.previous_sync')::timestamptz from drafts where id='30000000-0000-4000-8000-000000000001'),'drafts synced_at increases, ignores client value');
select is((select user_id from drafts where id='30000000-0000-4000-8000-000000000001'),'00000000-0000-4000-8000-000000000001'::uuid,'drafts ownership cannot be forged through sync');
select is(public.sync_push('[{"table": "drafts", "row": {"id": "30000000-0000-4000-8000-000000000001", "date": "2026-10-20", "kind": "quick", "text": "Changed draft", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T14:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": "2026-10-20T14:00:00Z"}}]'::jsonb)->'applied','["30000000-0000-4000-8000-000000000001"]'::jsonb,'drafts deletion applied');
select ok((select text='' from drafts where id='30000000-0000-4000-8000-000000000001'),'drafts tombstone clears all words');
select is(public.sync_push('[{"table": "drafts", "row": {"id": "30000000-0000-4000-8000-000000000001", "date": "2026-10-20", "kind": "quick", "text": "Changed draft", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T15:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": null}}]'::jsonb)->'applied','["30000000-0000-4000-8000-000000000001"]'::jsonb,'drafts later edit revives row');
select ok((select deleted_at is null from drafts where id='30000000-0000-4000-8000-000000000001'),'drafts revived');
select is(public.sync_push('[{"table": "settings", "row": {"theme": "night", "display_name": "Synthetic A", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T11:00:00Z"}}]'::jsonb)->'stale','["00000000-0000-4000-8000-000000000001"]'::jsonb,'settings older write is stale');
select is(public.sync_push('[{"table": "settings", "row": {"theme": "night", "display_name": "Synthetic A", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T12:00:00Z"}}]'::jsonb)->'stale','["00000000-0000-4000-8000-000000000001"]'::jsonb,'settings equal write is stale');
select is((select updated_at from settings where user_id='00000000-0000-4000-8000-000000000001'),'2026-10-20T12:00:00Z'::timestamptz,'settings stale writes unchanged');
select set_config('test.previous_sync',(select synced_at::text from settings where user_id='00000000-0000-4000-8000-000000000001'),true);
select is(public.sync_push('[{"table": "settings", "row": {"theme": "night", "display_name": "Synthetic A", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-20T13:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z"}}]'::jsonb)->'applied','["00000000-0000-4000-8000-000000000001"]'::jsonb,'settings newer write applied');
select ok((select synced_at > current_setting('test.previous_sync')::timestamptz from settings where user_id='00000000-0000-4000-8000-000000000001'),'settings synced_at increases, ignores client value');
select is((select user_id from settings where user_id='00000000-0000-4000-8000-000000000001'),'00000000-0000-4000-8000-000000000001'::uuid,'settings ownership cannot be forged through sync');
select is(public.sync_push('[]'),' {"applied":[],"stale":[]}'::jsonb,'Empty batch is valid');
select throws_ok($$select public.sync_push(null::jsonb)$$,'22023',null,'Reject malformed or unsupported batch');
select throws_ok($$select public.sync_push('null'::jsonb)$$,'22023',null,'Reject malformed or unsupported batch');
select throws_ok($$select public.sync_push('{}'::jsonb)$$,'22023',null,'Reject malformed or unsupported batch');
select throws_ok($$select public.sync_push('[{}]'::jsonb)$$,'22023',null,'Reject malformed or unsupported batch');
select throws_ok($$select public.sync_push('[ {"table":"ai_usage","row":{}} ]'::jsonb)$$,'22023',null,'Reject malformed or unsupported batch');
select throws_ok($$select public.sync_push((select jsonb_agg('{}'::jsonb) from generate_series(1,201)))$$,'22023',null,'Reject malformed or unsupported batch');
select throws_ok($$select public.sync_push('[{"table": "moments", "row": {"id": "10000000-0000-4000-8000-000000000021", "text": "Changed moment", "date": "2026-10-20", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-21T00:00:00Z", "user_id": "00000000-0000-4000-8000-000000000002", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": null}}]'::jsonb)$$,'42501',null,'Cannot hijack B record through conflict');
select throws_ok($$insert into public.moments (id,user_id,text,date,source,created_at,updated_at) values (gen_random_uuid(),'00000000-0000-4000-8000-000000000002','forged',current_date,'typed',now(),now())$$,'42501',null,'Direct foreign ownership rejected');
select throws_ok($$insert into public.moments(id,text,date,source,created_at,updated_at) values(gen_random_uuid(),repeat('x',4001),current_date,'typed',now(),now())$$,'23514',null,'Moment over 4000 rejected');
select throws_ok($$insert into public.diaries(id,date,created_at,updated_at) values(gen_random_uuid(),'2026-10-20',now(),now())$$,'23514',null,'Noncanonical diary id rejected');
select throws_ok($$insert into diaries(id,date,created_at,updated_at) values('92c455dc-32ee-5a1a-8ba7-e4bcc2d0a3a6','2026-10-20',now(),now())$$,'23505',null,'Second diary for same day rejected');
select throws_ok($$insert into chats(id,date,messages,state,created_at,updated_at) values(gen_random_uuid(),current_date,'[]',jsonb_build_object('input',repeat('x',260000)),now(),now())$$,'23514',null,'Oversized chat rejected');
select throws_ok($$select private.purge_tombstones()$$,'42501',null,'Client cannot invoke purge');
select is(public.sync_push('[{"table": "moments", "row": {"id": "a78ad459-f721-4eb5-bd70-d33ef9b52851", "text": "Changed moment", "date": "2026-10-22", "source": "typed", "created_at": "2026-10-20T12:00:00Z", "updated_at": "2026-10-22T12:00:00Z", "synced_at": "1900-01-01T00:00:00Z", "deleted_at": "2026-10-22T12:00:00Z"}}]'::jsonb)->'applied','["a78ad459-f721-4eb5-bd70-d33ef9b52851"]'::jsonb,'moments RPC inserts missing row');
select ok((select text='' from moments where id='a78ad459-f721-4eb5-bd70-d33ef9b52851'),'moments deleted insert clears words');
